#include "ynx_social_finite_joint_provider_source_private_v1.h"
#include <thread>
#include <new>
#include <mutex>
#include <unordered_set>
namespace {using S=ynx_social_joint_status_v1;S ok(){return{1,sizeof(S),0,0,0,0};}S error(int c){auto s=ok();s.error_present=1;s.original_first=c;return s;}bool valid(S s){return s.version==1&&s.size==sizeof(S)&&s.error_present<=1&&s.unknown<=1&&s.physical_done<=1&&(s.error_present||!s.original_first);}bool good(S s){return valid(s)&&!s.error_present&&!s.unknown;}bool closed(S s,bool null){return valid(s)&&s.physical_done==1&&null;}}
struct finite_joint_composition{
 const std::thread::id thread=std::this_thread::get_id();uint64_t go=0;ynx_social_joint_source_v1*source=nullptr;ynx_social_joint_binding_v1*binding=nullptr;S first=ok();bool retired=false,binding_selected=false,binding_done=false,source_selected=false,source_done=false;
 void remember(S s){if(!good(s)&&good(first))first=valid(s)?s:error(8);}
 bool same()const{return thread==std::this_thread::get_id();}
 S current(){if(!same())return error(4);if(retired)return error(7);if(!good(first))return first;S s{};ynx_auth_social_joint_provider_source_current_v1(go,&s);if(good(s))ynx_social_joint_source_current_v1(source,&s);if(good(s))ynx_social_joint_binding_current_v1(binding,&s);if(good(s))ynx_auth_social_joint_provider_source_current_v1(go,&s);remember(s);return s;}
 S join(){if(!same())return error(4);retired=true;if(binding_done){auto s=first;s.physical_done=1;return s;}if(binding_selected){auto s=first;if(good(s))s=error(8);s.unknown=1;return s;}if(!binding){binding_done=true;auto s=first;s.physical_done=1;return s;}binding_selected=true;S s{};ynx_social_joint_binding_close_v1(&binding,&s);remember(s);binding_done=closed(s,binding==nullptr);if(!binding_done&&good(first)){first=error(8);first.unknown=1;}auto out=first;out.physical_done=binding_done;if(!binding_done)out.unknown=1;return out;}
 S close(){auto s=join();if(!s.physical_done)return s;if(source_done){s=first;s.physical_done=1;return s;}if(source_selected){s=first;if(good(s))s=error(8);s.unknown=1;return s;}if(!source){source_done=true;s=first;s.physical_done=1;return s;}source_selected=true;S next{};ynx_social_joint_source_close_v1(&source,&next);remember(next);source_done=closed(next,source==nullptr);if(!source_done&&good(first)){first=error(8);first.unknown=1;}s=first;s.physical_done=source_done;if(!source_done)s.unknown=1;return s;}
};
namespace{std::mutex owners_mutex;std::unordered_set<finite_joint_composition*>owners;bool known(finite_joint_composition*p){std::lock_guard<std::mutex>l(owners_mutex);return owners.count(p)!=0;}bool adopt(finite_joint_composition*p){std::lock_guard<std::mutex>l(owners_mutex);if(owners.size()>=16384)return false;owners.insert(p);return true;}}
extern "C" void finite_joint_composition_open(uint64_t go,ynx_social_joint_source_input_v1*in,const unsigned char*id,size_t n,finite_joint_composition**out,S*status){if(!status)return;if(!out){*status=error(2);return;}*out=nullptr;if(!go||!in||in->version!=2||in->size!=sizeof(*in)||!in->same_process_capture_reference||!id||n!=32){*status=error(2);return;}auto*p=new(std::nothrow)finite_joint_composition;if(!p){*status=error(3);return;}if(!adopt(p)){delete p;*status=error(8);return;}*out=p;p->go=go;S s{};ynx_auth_social_joint_provider_source_current_v1(go,&s);if(good(s))ynx_social_joint_source_open_v1(in,&p->source,&s);if(good(s)&&!p->source)s=error(8);if(good(s))ynx_social_joint_binding_open_v1(p->source,id,n,&p->binding,&s);if(good(s)&&!p->binding)s=error(8);p->remember(s);*status=good(s)?p->current():s;}
extern "C" void finite_joint_composition_current(finite_joint_composition*p,S*s){if(s)*s=known(p)?p->current():error(1);}
extern "C" void finite_joint_composition_seal(finite_joint_composition*p,uint32_t role,ynx_social_joint_bytes_v1 body,ynx_social_joint_bytes_v1 frame,S*s){if(!s)return;if(!known(p)){*s=error(1);return;}*s=p->current();if(!good(*s))return;ynx_auth_social_joint_provider_source_seal_original_v1(p->go,p->source,p->binding,role,body,frame,s);p->remember(*s);if(good(*s))*s=p->current();}
extern "C" void finite_joint_composition_join(finite_joint_composition*p,S*s){if(s)*s=known(p)?p->join():error(1);}
extern "C" void finite_joint_composition_close(finite_joint_composition**p,S*s){if(!s)return;if(!p||!known(*p)){*s=error(1);return;}auto out=(*p)->close();if(out.physical_done&&(*p)->source_done&&(*p)->binding_done)*p=nullptr;*s=out;}
